        msg = f"Repository text corpus snapshot lacks selected address: {address}."
        raise ValueError(msg)
    if len(matches) != 1:
        msg = f"Repository text corpus snapshot repeats selected address: {address}."
        raise ValueError(msg)
    return matches[0]


